import sys
import lzma

def main():
    if len(sys.argv) != 2 or sys.argv[1] not in ("c", "d"):
        sys.stderr.write("usage: squeeze.py c|d\n")
        sys.exit(2)
    data = sys.stdin.buffer.read()
    if sys.argv[1] == "c":
        out = lzma.compress(
            data,
            format=lzma.FORMAT_RAW,
            filters=[{"id": lzma.FILTER_LZMA2, "preset": 9 | lzma.PRESET_EXTREME}],
        )
    else:
        out = lzma.decompress(
            data,
            format=lzma.FORMAT_RAW,
            filters=[{"id": lzma.FILTER_LZMA2, "preset": 9 | lzma.PRESET_EXTREME}],
        )
    sys.stdout.buffer.write(out)

if __name__ == "__main__":
    main()

import sys
import lzma

CONFS = [(3, 0, 2), (0, 0, 0), (1, 0, 0), (4, 0, 0), (3, 0, 0), (2, 0, 0), (0, 0, 2), (1, 0, 2)]

def filt(i):
    lc, lp, pb = CONFS[i]
    return [{"id": lzma.FILTER_LZMA2, "preset": 9 | lzma.PRESET_EXTREME, "lc": lc, "lp": lp, "pb": pb}]

def main():
    if len(sys.argv) != 2 or sys.argv[1] not in ("c", "d"):
        sys.stderr.write("usage: squeeze.py c|d\n")
        sys.exit(2)
    data = sys.stdin.buffer.read()
    if sys.argv[1] == "c":
        best = None
        for i in range(len(CONFS)):
            out = lzma.compress(data, format=lzma.FORMAT_RAW, filters=filt(i))
            if best is None or len(out) < len(best[1]):
                best = (i, out)
        sys.stdout.buffer.write(bytes([best[0]]) + best[1])
    else:
        i = data[0]
        out = lzma.decompress(data[1:], format=lzma.FORMAT_RAW, filters=filt(i))
        sys.stdout.buffer.write(out)

if __name__ == "__main__":
    main()

